python3 << 'PYEOF'
import json

with open('/tmp/edata.json') as f:
    d = json.load(f)

# Prepare JS-ready arrays
price_dates = json.dumps([x[0] for x in d['price']])
price_vals  = json.dumps([x[1] for x in d['price']])
vol30_dates = json.dumps([x[0] for x in d['vol30d']])
vol30_vals  = json.dumps([x[1] for x in d['vol30d']])
vol90_vals  = json.dumps([x[1] for x in d['vol90d']])
dd_dates    = json.dumps([x[0] for x in d['drawdown']])
dd_vals     = json.dumps([x[1] for x in d['drawdown']])

annual_years   = json.dumps(d['annual_years'])
annual_returns = json.dumps(d['annual_returns'])

monthly_means  = json.dumps(d['monthly_means'])
monthly_tstats = json.dumps(d['monthly_tstats'])

heatmap_years = json.dumps(d['heatmap_years'])
heatmap_data  = json.dumps(d['heatmap_data'])

vol_years = json.dumps(d['vol_years'])
vol_vals2 = json.dumps(d['vol_vals'])

hist_x     = json.dumps(d['hist_x'])
hist_y     = json.dumps(d['hist_y'])
normal_y   = json.dumps(d['normal_y'])

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Gold Price Dynamics: Trend &amp; Volatility Analysis (2000–2025)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
<style>
  :root {{
    --gold: #C9A84C;
    --gold-light: #F0D080;
    --gold-dark: #8B6914;
    --bg: #0F1117;
    --bg2: #181C24;
    --bg3: #1E2330;
    --border: #2A3040;
    --text: #E8EAF0;
    --text-dim: #8892A4;
    --green: #2ECC71;
    --red: #E74C3C;
    --blue: #5DADE2;
    --orange: #E67E22;
    --purple: #9B59B6;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    font-size: 14px;
    line-height: 1.6;
  }}
  /* HEADER */
  .report-header {{
    background: linear-gradient(135deg, #0a0c12 0%, #1a1400 40%, #0a0c12 100%);
    border-bottom: 2px solid var(--gold-dark);
    padding: 48px 64px 40px;
    position: relative;
    overflow: hidden;
  }}
  .report-header::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 60% 50%, rgba(201,168,76,0.08) 0%, transparent 70%);
    pointer-events: none;
  }}
  .header-tag {{
    font-size: 11px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 16px;
    font-weight: 600;
  }}
  .report-header h1 {{
    font-size: 36px;
    font-weight: 700;
    color: #fff;
    line-height: 1.2;
    margin-bottom: 12px;
  }}
  .report-header h1 span {{ color: var(--gold); }}
  .report-subtitle {{
    font-size: 15px;
    color: var(--text-dim);
    max-width: 700px;
    margin-bottom: 24px;
  }}
  .header-meta {{
    display: flex; gap: 32px; flex-wrap: wrap;
  }}
  .meta-item {{
    font-size: 12px;
    color: var(--text-dim);
  }}
  .meta-item strong {{
    color: var(--gold-light);
    font-weight: 600;
  }}
  /* LAYOUT */
  .container {{
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 32px;
  }}
  /* NAV */
  .toc {{
    background: var(--bg2);
    border-bottom: 1px solid var(--border);
    padding: 0 64px;
    position: sticky;
    top: 0;
    z-index: 100;
  }}
  .toc ul {{
    display: flex;
    list-style: none;
    gap: 0;
    overflow-x: auto;
  }}
  .toc a {{
    display: block;
    padding: 14px 18px;
    color: var(--text-dim);
    text-decoration: none;
    font-size: 12px;
    font-weight: 500;
    letter-spacing: 0.5px;
    border-bottom: 2px solid transparent;
    white-space: nowrap;
    transition: color 0.2s, border-color 0.2s;
  }}
  .toc a:hover {{ color: var(--gold); border-bottom-color: var(--gold); }}
  /* SECTION */
  .section {{
    padding: 56px 64px 48px;
    border-bottom: 1px solid var(--border);
  }}
  .section-label {{
    font-size: 11px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold);
    font-weight: 600;
    margin-bottom: 8px;
  }}
  .section h2 {{
    font-size: 26px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 8px;
  }}
  .section-desc {{
    color: var(--text-dim);
    font-size: 14px;
    margin-bottom: 32px;
    max-width: 900px;
  }}
  /* KPI CARDS */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 48px;
  }}
  .kpi-card {{
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 20px 16px;
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--gold);
  }}
  .kpi-label {{
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-dim);
    margin-bottom: 8px;
    font-weight: 600;
  }}
  .kpi-value {{
    font-size: 28px;
    font-weight: 700;
    color: var(--gold-light);
    line-height: 1;
    margin-bottom: 6px;
  }}
  .kpi-sub {{
    font-size: 11px;
    color: var(--text-dim);
  }}
  /* CHARTS */
  .chart-wrapper {{
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
  }}
  .chart-title {{
    font-size: 14px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 4px;
  }}
  .chart-sub {{
    font-size: 12px;
    color: var(--text-dim);
    margin-bottom: 20px;
  }}
  canvas {{ display: block; }}
  /* TWO-COL LAYOUT */
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }}
  .three-col {{
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }}
  /* REGIME LEGEND */
  .regime-legend {{
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    margin-bottom: 16px;
  }}
  .regime-item {{
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--text-dim);
  }}
  .regime-dot {{
    width: 12px;
    height: 12px;
    border-radius: 3px;
  }}
  /* ANALYSIS TABLE */
  .analysis-table {{
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 24px;
    font-size: 13px;
  }}
  .analysis-table th {{
    background: var(--bg3);
    color: var(--text-dim);
    text-transform: uppercase;
    font-size: 11px;
    letter-spacing: 1px;
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
    font-weight: 600;
  }}
  .analysis-table td {{
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }}
  .analysis-table tr:hover td {{ background: var(--bg3); }}
  .analysis-table .positive {{ color: var(--green); font-weight: 600; }}
  .analysis-table .negative {{ color: var(--red); font-weight: 600; }}
  .analysis-table .neutral  {{ color: var(--text-dim); }}
  /* INSIGHT BOXES */
  .insight-grid {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 24px;
  }}
  .insight-box {{
    background: var(--bg3);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px;
  }}
  .insight-box .insight-title {{
    font-size: 12px;
    font-weight: 600;
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
  }}
  .insight-box p {{
    font-size: 13px;
    color: var(--text-dim);
    line-height: 1.5;
  }}
  .insight-box p strong {{ color: var(--text); }}
  /* HEATMAP */
  #heatmapContainer {{
    overflow-x: auto;
  }}
  .heatmap-table {{
    border-collapse: collapse;
    font-size: 11px;
    white-space: nowrap;
  }}
  .heatmap-table th {{
    background: var(--bg3);
    color: var(--text-dim);
    padding: 6px 10px;
    font-weight: 600;
    text-align: center;
    border: 1px solid var(--border);
    font-size: 11px;
  }}
  .heatmap-table td {{
    padding: 5px 8px;
    text-align: center;
    border: 1px solid var(--border);
    font-size: 11px;
    min-width: 52px;
  }}
  .heatmap-table .year-label {{
    color: var(--text-dim);
    font-weight: 600;
    background: var(--bg3);
    text-align: left;
    padding: 5px 10px;
    min-width: 50px;
  }}
  /* SIGNAL TABLE */
  .signal-badge {{
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
  }}
  .badge-golden {{ background: rgba(46,204,113,0.15); color: var(--green); border: 1px solid rgba(46,204,113,0.3); }}
  .badge-death  {{ background: rgba(231,76,60,0.15);  color: var(--red);   border: 1px solid rgba(231,76,60,0.3); }}
  /* FOOTER */
  .report-footer {{
    background: var(--bg2);
    border-top: 1px solid var(--border);
    padding: 32px 64px;
    font-size: 12px;
    color: var(--text-dim);
  }}
  .footer-disclaimer {{
    font-size: 11px;
    color: #4A5568;
    margin-top: 12px;
    line-height: 1.5;
  }}
  @media (max-width: 1100px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .two-col, .three-col, .insight-grid {{ grid-template-columns: 1fr; }}
    .section {{ padding: 40px 24px; }}
    .report-header {{ padding: 40px 24px; }}
    .toc {{ padding: 0 24px; }}
  }}
</style>
</head>
<body>

<!-- HEADER -->
<div class="report-header">
  <div class="header-tag">Analyst Intelligence Report &bull; Macro Assets</div>
  <h1>Gold Price <span>Dynamics</span></h1>
  <h1 style="font-size:22px;font-weight:400;color:#aab;margin-top:4px;">A Comprehensive Trend &amp; Volatility Analysis (2000–2026)</h1>
  <p class="report-subtitle">Daily OHLCV analysis of gold spanning 25+ years: price regimes, volatility clustering, seasonal edges, tail-risk profiling, and momentum dynamics — all derived from 6,399 trading days.</p>
  <div class="header-meta">
    <div class="meta-item"><strong>Dataset:</strong> Aug 2000 – Mar 2026</div>
    <div class="meta-item"><strong>Frequency:</strong> Daily (Trading Days)</div>
    <div class="meta-item"><strong>Records:</strong> 6,399</div>
    <div class="meta-item"><strong>Price Start:</strong> $273.90</div>
    <div class="meta-item"><strong>Price End:</strong> $5,377.30</div>
    <div class="meta-item"><strong>Source:</strong> Kaggle / krupalpatel07</div>
  </div>
</div>

<!-- NAV -->
<nav class="toc">
  <ul>
    <li><a href="#kpis">KPI Summary</a></li>
    <li><a href="#market-overview">Market Overview</a></li>
    <li><a href="#volatility-analysis">Volatility &amp; Regimes</a></li>
    <li><a href="#seasonal-patterns">Seasonal Patterns</a></li>
    <li><a href="#return-distribution">Return Distribution</a></li>
    <li><a href="#momentum-liquidity">Momentum &amp; Liquidity</a></li>
    <li><a href="#key-takeaways">Key Takeaways</a></li>
  </ul>
</nav>

<!-- SECTION 0: KPI SUMMARY -->
<section class="section" id="kpis">
  <div class="section-label">Performance Summary</div>
  <h2>Key Performance Indicators</h2>
  <p class="section-desc">Full-period metrics across 6,399 trading days from August 30, 2000 to March 3, 2026. All figures derived exclusively from closing prices.</p>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">CAGR (Annualized Return)</div>
      <div class="kpi-value">12.38%</div>
      <div class="kpi-sub">Aug 2000 → Mar 2026 (25.5 yrs)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Annualized Volatility</div>
      <div class="kpi-value">17.69%</div>
      <div class="kpi-sub">Daily log-return std × √252</div>
    </div>
    <div class="kpi-card" style="--gold: #E74C3C;">
      <div class="kpi-label">Maximum Drawdown</div>
      <div class="kpi-value" style="color:#E74C3C;">−44.36%</div>
      <div class="kpi-sub">Peak Aug 22, 2011 → Trough Dec 17, 2015</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Avg Daily Volume</div>
      <div class="kpi-value">4,283</div>
      <div class="kpi-sub">4,766 post-2003 (reliable period)</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Sharpe-Like Ratio</div>
      <div class="kpi-value">0.700</div>
      <div class="kpi-sub">CAGR / Ann. Vol (0% risk-free)</div>
    </div>
  </div>

  <div class="chart-wrapper">
    <div class="chart-title">Full-Period Performance Snapshot</div>
    <div class="chart-sub">Price appreciation from $273.90 to $5,377.30 — a 19.6× total return over 25.5 years</div>
    <table class="analysis-table">
      <thead>
        <tr>
          <th>Metric</th>
          <th>Value</th>
          <th>Context</th>
        </tr>
      </thead>
      <tbody>
        <tr><td>Starting Price</td><td>$273.90</td><td class="neutral">Aug 30, 2000</td></tr>
        <tr><td>Ending Price</td><td>$5,377.30</td><td class="neutral">Mar 3, 2026</td></tr>
        <tr><td>All-Time High</td><td>$5,405.00</td><td class="positive">Intraday high reached in dataset</td></tr>
        <tr><td>All-Time Low (in period)</td><td>$255.10</td><td class="neutral">Early 2001</td></tr>
        <tr><td>Total Return</td><td class="positive">+1,862%</td><td class="positive">19.6× price multiplier</td></tr>
        <tr><td>CAGR</td><td class="positive">12.38%</td><td class="neutral">Consistent long-run compounder</td></tr>
        <tr><td>Annualized Volatility</td><td>17.69%</td><td class="neutral">Comparable to large-cap equity</td></tr>
        <tr><td>Max Drawdown</td><td class="negative">−44.36%</td><td class="negative">Sep 2011 peak to Dec 2015 trough</td></tr>
        <tr><td>Sharpe-Like Ratio</td><td>0.700</td><td class="neutral">Solid risk-adjusted return</td></tr>
        <tr><td>Daily Return Mean</td><td class="positive">+0.0465%</td><td class="neutral">Modest but consistent positive drift</td></tr>
        <tr><td>Daily Return Std Dev</td><td>1.11%</td><td class="neutral">Typical daily swing magnitude</td></tr>
        <tr><td>Skewness</td><td class="negative">−0.47</td><td class="negative">Slight negative skew — left-tail events</td></tr>
        <tr><td>Excess Kurtosis</td><td class="negative">7.02</td><td class="negative">Fat tails — returns not normally distributed</td></tr>
      </tbody>
    </table>
  </div>
</section>

<!-- SECTION 1: MARKET OVERVIEW -->
<section class="section" id="market-overview">
  <div class="section-label">Section 01</div>
  <h2>Market Overview &amp; Long-Term Price Trend</h2>
  <p class="section-desc">Gold's 25-year trajectory through four distinct macro regimes: a bear-to-base transition (2000–2001), a structural bull run (2002–2011), a correction cycle (2012–2018), and a renewed bull market with accelerating momentum (2019–2026).</p>

  <div class="chart-wrapper">
    <div class="chart-title">Gold Closing Price — Daily (2000–2026)</div>
    <div class="chart-sub">Log-scale view recommended to appreciate compounding. Regime shading identifies the four major structural phases.</div>
    <canvas id="priceChart" height="90"></canvas>
  </div>

  <div class="two-col">
    <div class="chart-wrapper" style="margin-bottom:0">
      <div class="chart-title">Annual Returns (%)</div>
      <div class="chart-sub">Year-over-year price change from first to last trading day</div>
      <canvas id="annualReturnsChart" height="180"></canvas>
    </div>
