(function() {{
  const container = document.getElementById('heatmapContainer');
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  function colorForVal(v) {{
    if (v === null || v === undefined) return '#1E2330';
    const clamp = Math.max(-0.5, Math.min(0.5, v));
    if (clamp >= 0) {{
      const intensity = Math.min(1, clamp / 0.3);
      const r = Math.round(30 + (46-30)*intensity);
      const g = Math.round(35 + (204-35)*intensity);
      const b = Math.round(48 + (113-48)*intensity);
      return `rgb(${{r}},${{g}},${{b}})`;
    }} else {{
      const intensity = Math.min(1, Math.abs(clamp) / 0.3);
      const r = Math.round(30 + (231-30)*intensity);
      const g = Math.round(35 + (76-35)*intensity);
      const b = Math.round(48 + (60-48)*intensity);
      return `rgb(${{r}},${{g}},${{b}})`;
    }}
  }}

  let html = '<table class="heatmap-table"><thead><tr><th>Year</th>';
  months.forEach(m => html += `<th>${{m}}</th>`);
  html += '</tr></thead><tbody>';

  heatmapYears.forEach((year, yi) => {{
    html += `<tr><td class="year-label">${{year}}</td>`;
    for (let mi = 0; mi < 12; mi++) {{
      const v = heatmapData[yi][mi];
      const bg = colorForVal(v);
      const textColor = v === null ? '#4A5568' : (Math.abs(v||0) > 0.2 ? '#fff' : '#ccc');
      const display = v === null ? '—' : v.toFixed(2);
      html += `<td style="background:${{bg}};color:${{textColor}}">${{display}}</td>`;
    }}
    html += '</tr>';
  }});

  html += '</tbody></table>';
  container.innerHTML = html;
}})();

